detection_pack.kql:
// ================================================================
// KQL — Microsoft Sentinel / Defender XDR
// APEX Advisory: Hackers target WordPress sites in miniOrange auth bypass att
// CVE: CDB-ADVISORY-HACKERS-TARGET-WORDPRESS-SITES | Class: AUTH_BYPASS | APEX v184.0
// Generated: 2026-10-21
// ================================================================

let lookback = 30d;


// Alert rule: SecurityAlert table correlation
SecurityAlert
| where TimeGenerated > ago(lookback)
| where AlertName contains "CDB-ADVISORY-HACKERS-TARGET-WORDPRESS-SITES" or Description contains "CDB-ADVISORY-HACKERS-TARGET-WORDPRESS-SITES"
| extend Rule = "APEX-CDB-ADVISORY-HACKERS-TARGET-WORDPRESS-SITES-ALERT"
| project TimeGenerated, AlertName, AlertSeverity, Entities, Description, Rule
| order by TimeGenerated desc;

